import{_ as o,C as n,o as s,c as e,j as i,E as d,a as l,a2 as r}from"./chunks/framework.C21TwvGF.js";const x=JSON.parse('{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"n":3,"bob":"I-bob · Android muhiti va dasturlash asoslari","lessons":[{"g":7,"title":"Android Studio va Android SDK bilan tanishuv (2-qism)","lead":"Android Studio va Android SDK bilan tanishuv (2-qism): Loyiha strukturasi (java/kotlin, res, AndroidManifest.xml, Gradle)","link":"/mentor/9-sinf-android/hafta-03/dars-1","slide":"/slaydlar/9-sinf-android/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-android/hafta-03/dars-1-test.html"},{"g":8,"title":"Android Studio va Android SDK bilan tanishuv (3-qism)","lead":"Android Studio va Android SDK bilan tanishuv (3-qism): Birinchi «Hello World» ilovasini yaratish va Gradle build mexanizmi","link":"/mentor/9-sinf-android/hafta-03/dars-2","slide":"/slaydlar/9-sinf-android/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-android/hafta-03/dars-2-test.html"},{"g":9,"title":"Simulyator va Emulator haqida tushuncha (1-qism)","lead":"Simulyator va Emulator haqida tushuncha (1-qism): Simulyator vs Emulyator farqi, AVD yaratish va CPU virtualizatsiyasi","link":"/mentor/9-sinf-android/hafta-03/dars-3","slide":"/slaydlar/9-sinf-android/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf-android/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-03/index.md","filePath":"mentor/9-sinf-android/hafta-03/index.md"}'),h={name:"mentor/9-sinf-android/hafta-03/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},c={class:"blk"},v={id:"baholash-mezoni",tabindex:"-1"};function b(y,a,g,f,q,k){const t=n("Icon");return s(),e("div",null,[i("div",u,[i("h2",m,[d(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=r('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h2 id="_7-dars-android-studio-va-android-sdk-bilan-tanishuv-2-qism" tabindex="-1">7-dars. Android Studio va Android SDK bilan tanishuv (2-qism) <a class="header-anchor" href="#_7-dars-android-studio-va-android-sdk-bilan-tanishuv-2-qism" aria-label="Permalink to &quot;7-dars. Android Studio va Android SDK bilan tanishuv (2-qism)&quot;">​</a></h2><ol><li>Android loyihasidagi 4 ta asosiy katalog va fayllarning (<code>java/</code>, <code>res/layout/</code>, <code>res/values/strings.xml</code>, <code>AndroidManifest.xml</code>) vazifasini daftaringizga yozing.</li><li>Ilovada yangi til (masalan, rus tili yoki ingliz tili) qo&#39;shish uchun <code>res/</code> papkasida qanday fayllar yaratilishini tushuntiring.</li><li><code>minSdk</code>, <code>targetSdk</code> va <code>compileSdk</code> nima ekanini va nima sababdan <code>minSdk</code> ilova o&#39;rnatilishi mumkin bo&#39;lgan telefonlar doirasini cheklashini bayon qiling.</li></ol><hr><h2 id="_8-dars-android-studio-va-android-sdk-bilan-tanishuv-3-qism" tabindex="-1">8-dars. Android Studio va Android SDK bilan tanishuv (3-qism) <a class="header-anchor" href="#_8-dars-android-studio-va-android-sdk-bilan-tanishuv-3-qism" aria-label="Permalink to &quot;8-dars. Android Studio va Android SDK bilan tanishuv (3-qism)&quot;">​</a></h2><ol><li>Kompyuteringizda Android Studio orqali <code>MeningBirinchiIlovam</code> loyihasini yarating. Ekranga o&#39;z ism-familiyangizni va sinfingizni chiqaring.</li><li>Ekrondagi <code>TextView</code> matnini 28sp qilib, rangini to&#39;q yashil (<code>#2E7D32</code>) qilib sozlang.</li><li><code>Alt + Enter</code> (Extract string resource) orqali matnni <code>strings.xml</code> fayliga o&#39;tkazing va <code>strings.xml</code> fayli skrinshotini oling.</li><li>&quot;Run&quot; tugmasi bosilganda nima sodir bo&#39;lishini (Gradle build, aapt2, d8, APK va ADB) bosqichma-bosqich yozing.</li></ol><hr><h2 id="_9-dars-simulyator-va-emulator-haqida-tushuncha-1-qism" tabindex="-1">9-dars. Simulyator va Emulator haqida tushuncha (1-qism) <a class="header-anchor" href="#_9-dars-simulyator-va-emulator-haqida-tushuncha-1-qism" aria-label="Permalink to &quot;9-dars. Simulyator va Emulator haqida tushuncha (1-qism)&quot;">​</a></h2><ol><li>Simulyator va Emulyator o&#39;rtasidagi 2 ta eng muhim texnik farqni yozma tushuntiring.</li><li>Android Studio&#39;da AVD (Android Virtual Device) yaratish qadamlarini (Device, System Image: Google APIs, RAM ajratish) tasvirlang.</li><li>Nima uchun kompyuter BIOS sozlamalarida apparat virtualizatsiyasi (Intel VT-x / AMD-V) yoqilgan bo&#39;lishi shartligini tushuntiring.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-100-ballik-tizim" tabindex="-1">Baholash mezonlari (100 ballik tizim) <a class="header-anchor" href="#baholash-mezonlari-100-ballik-tizim" aria-label="Permalink to &quot;Baholash mezonlari (100 ballik tizim)&quot;">​</a></h3><ol><li><p><strong>Loyiha tuzilmasi va resurslar (30 ball):</strong></p><ul><li>Loyiha kataloglari vazifalarini to&#39;g&#39;ri tushuntirishi (10 ball);</li><li><code>AndroidManifest.xml</code> va ruxsatnomalar rolini bilishi (10 ball);</li><li><code>strings.xml</code> va lokalizatsiya tamoyillarini to&#39;g&#39;ri qo&#39;llay olishi (10 ball).</li></ul></li><li><p><strong>Birinchi ilova va XML dizayn (35 ball):</strong></p><ul><li>Loyihani xatosiz yaratishi va parametrlarni to&#39;g&#39;ri sozlashi (10 ball);</li><li><code>TextView</code> atributlari (<code>textSize</code>, <code>textColor</code>) va <code>sp</code> birligidan to&#39;g&#39;ri foydalanishi (15 ball);</li><li>Gradle build bosqichlarini va <code>setContentView</code> vazifasini tushunishi (10 ball).</li></ul></li><li><p><strong>Emulyator va virtualizatsiya (35 ball):</strong></p><ul><li>Simulyator va Emulyator farqini ilmiy asoslay olishi (15 ball);</li><li>AVD sozlamalari va Google APIs ahamiyatini bilishi (10 ball);</li><li>CPU virtualizatsiyasi (VT-x / AMD-V) vazifasini tushunishi (10 ball).</li></ul></li></ol><h3 id="kutiladigan-namunaviy-natijalar" tabindex="-1">Kutiladigan namunaviy natijalar <a class="header-anchor" href="#kutiladigan-namunaviy-natijalar" aria-label="Permalink to &quot;Kutiladigan namunaviy natijalar&quot;">​</a></h3><ul><li>O&#39;quvchi matn o&#39;lchov birligi sifatida <code>dp</code> emas, balki <code>sp</code> (scale-independent pixels) ishlatilishining sababini to&#39;g&#39;ri asoslay olishi shart;</li><li>Emulyator apparat ta&#39;minotini to&#39;liq modellashtirishi va nima sababdan BIOS&#39;da virtualizatsiya talab etilishi aniq ifodalanishi kerak.</li></ul>',16))]),i("div",c,[i("h2",v,[d(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=r('<p><strong>Mavzular:</strong></p><ol><li>Android Studio va Android SDK bilan tanishuv (2-qism): Loyiha strukturasi (java/kotlin, res, AndroidManifest.xml, Gradle)</li><li>Android Studio va Android SDK bilan tanishuv (3-qism): Birinchi «Hello World» ilovasini yaratish va Gradle build mexanizmi</li><li>Simulyator va Emulator haqida tushuncha (1-qism): Simulyator vs Emulyator farqi, AVD yaratish va CPU virtualizatsiyasi</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Loyiha strukturasi</strong></td><td>java/kotlin, res, AndroidManifest.xml, strings.xml va Gradle parametrlari</td><td>30 ball</td></tr><tr><td><strong>Birinchi «Hello World» ilovasi</strong></td><td>Loyiha yaratish, TextView, sp birligi, Extract string resource, setContentView</td><td>35 ball</td></tr><tr><td><strong>Emulyator va virtualizatsiya</strong></td><td>Simulyator vs Emulyator, AVD Manager, Intel VT-x / AMD-V, Extended Controls</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Struktura (30)</th><th>Birinchi ilova (35)</th><th>Emulyator (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar matn o&#39;lchamini <code>dp</code> yoki <code>px</code> da belgilashga moyil bo&#39;lishadi. Shuningdek, kompyuterlarda Intel VT-x o&#39;chirilgan bo&#39;lsa, emulyator ochilmasligi mumkin. Bunday hollarda BIOS sozlamalarini tekshirish lozim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> <code>activity_main.xml</code> ichiga yangi <code>Button</code> (tugma) yoki <code>ImageView</code> qo&#39;shib, uning parametrlarini mustaqil sozlash vazifasi berilishi mumkin.</li></ul>',11))])])}const A=o(h,[["render",b]]);export{x as __pageData,A as default};
